--
-- Name: acquire_refresh_lock(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_refresh_lock(p_user_id text, p_ttl_seconds integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
  v_acquired boolean;
begin
  insert into public.shopify_refresh_locks as l (user_id, locked_until)
  values (p_user_id, now() + make_interval(secs => p_ttl_seconds))
  on conflict (user_id) do update
    set locked_until = excluded.locked_until
    where l.locked_until < now()
  returning true into v_acquired;

  return coalesce(v_acquired, false);
end;
$$;


--
-- Name: add_user_credits(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_user_credits(p_user_id text, p_credits integer, p_purchased integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  u public.user_integrations%rowtype;
  new_balance integer;
begin
  if p_credits is null or p_credits <= 0 then
    raise exception 'invalid_credit_amount';
  end if;
  select * into u from public.user_integrations where clerk_user_id = p_user_id for update;
  if not found then raise exception 'integration_not_found'; end if;

  new_balance := coalesce((to_jsonb(u)->>'credits')::integer, u.credits_balance, 0) + p_credits;
  update public.user_integrations
     set credits_balance = new_balance,
         credits_total_purchased = coalesce(credits_total_purchased, 0) + coalesce(p_purchased, 0)
   where clerk_user_id = p_user_id;
  if to_jsonb(u) ? 'credits' then
    execute 'update public.user_integrations set credits = $1 where clerk_user_id = $2'
      using new_balance, p_user_id;
  end if;
  return new_balance;
end;
$_$;


--
-- Name: apply_credit_adjustment(text, text, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_credit_adjustment(p_idempotency_key text, p_user_id text, p_delta integer, p_reason text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  u public.user_integrations%rowtype;
  before_balance integer;
  after_balance integer;
begin
  if coalesce(trim(p_idempotency_key), '') = '' or coalesce(trim(p_reason), '') = '' then
    raise exception 'adjustment_key_and_reason_required';
  end if;
  select * into u from public.user_integrations where clerk_user_id = p_user_id for update;
  if not found then raise exception 'integration_not_found'; end if;
  if exists (select 1 from public.credit_adjustments where idempotency_key = p_idempotency_key) then
    return 'already_applied';
  end if;

  before_balance := coalesce((to_jsonb(u)->>'credits')::integer, u.credits_balance, 0);
  after_balance := before_balance + p_delta;
  if after_balance < 0 then raise exception 'adjustment_would_make_balance_negative'; end if;

  update public.user_integrations set credits_balance = after_balance where clerk_user_id = p_user_id;
  if to_jsonb(u) ? 'credits' then
    execute 'update public.user_integrations set credits = $1 where clerk_user_id = $2' using after_balance, p_user_id;
  end if;
  insert into public.credit_adjustments (idempotency_key, clerk_user_id, delta, reason, evidence, balance_before, balance_after)
  values (p_idempotency_key, p_user_id, p_delta, p_reason, p_evidence, before_balance, after_balance);
  return 'applied';
end;
$_$;


--
-- Name: check_rate_limit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rate_limit(p_key text, p_limit integer, p_window_seconds integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
  v_now   timestamptz := now();
  v_count integer;
begin
  insert into public.rate_limits as rl (key, count, window_start)
  values (p_key, 1, v_now)
  on conflict (key) do update
    set count = case
          when rl.window_start < v_now - make_interval(secs => p_window_seconds)
            then 1
          else rl.count + 1
        end,
        window_start = case
          when rl.window_start < v_now - make_interval(secs => p_window_seconds)
            then v_now
          else rl.window_start
        end
  returning rl.count into v_count;

  return v_count <= p_limit;
end;
$$;


--
-- Name: commit_brief_generation(text, uuid, text, uuid, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commit_brief_generation(p_user_id text, p_request_id uuid, p_request_hash text, p_campaign_id uuid, p_campaign jsonb, p_copy jsonb, p_context jsonb, p_response jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  u public.user_integrations%rowtype;
  c public.campaigns%rowtype;
  prior public.brief_generation_receipts%rowtype;
  v_campaign_id uuid;
  v_version_id uuid;
  v_attempt integer;
  v_balance integer;
  v_unlimited boolean;
  v_result jsonb;
begin
  select * into u from public.user_integrations where clerk_user_id = p_user_id for update;
  if not found then raise exception 'integration_not_found'; end if;

  select * into prior from public.brief_generation_receipts where clerk_user_id = p_user_id and request_id = p_request_id;
  if found then
    if prior.request_hash <> p_request_hash then raise exception 'idempotency_conflict'; end if;
    return prior.response;
  end if;

  v_balance := coalesce((to_jsonb(u)->>'credits')::integer, u.credits_balance, 0);
  v_unlimited := coalesce(u.credits_unlimited_until > now(), false);

  if p_campaign_id is not null then
    select * into c from public.campaigns where id = p_campaign_id and clerk_user_id = p_user_id for update;
    if not found then raise exception 'invalid_regeneration'; end if;

    if c.product_name is distinct from p_campaign->>'product_name'
       or c.product_description is distinct from p_campaign->>'product_description'
       or c.campaign_goal is distinct from p_campaign->>'campaign_goal'
       or c.product_price is distinct from p_campaign->>'product_price' then
      raise exception 'regeneration_product_changed';
    end if;

    select count(*) + 1 into v_attempt from public.campaign_brief_versions cbv where cbv.campaign_id = c.id and cbv.clerk_user_id = p_user_id;
    if v_attempt < 2 or v_attempt > 4 then raise exception 'regeneration_limit'; end if;
    v_campaign_id := c.id;
  else
    if not v_unlimited and v_balance < 1 then raise exception 'no_credits'; end if;

    insert into public.campaigns (
      clerk_user_id, status, brand_name, product_name, product_description, target_audience,
      campaign_goal, tone_preference, platform, media_url, product_price, headline, primary_text,
      description, cta, copywriter_note, brief_data
    )
    values (
      p_user_id, 'draft', p_campaign->>'brand_name', p_campaign->>'product_name', p_campaign->>'product_description',
      p_campaign->>'target_audience', p_campaign->>'campaign_goal', p_campaign->>'tone_preference', p_campaign->>'platform',
      p_campaign->>'media_url', p_campaign->>'product_price', p_copy->>'headline', p_copy->>'primary_text',
      p_copy->>'description', p_copy->>'cta', p_copy->>'copywriter_note', p_context
    ) returning id into v_campaign_id;

    v_attempt := 1;

    if not v_unlimited then
      v_balance := v_balance - 1;
      update public.user_integrations set credits_balance = v_balance where clerk_user_id = p_user_id;
      if to_jsonb(u) ? 'credits' then
        execute 'update public.user_integrations set credits = $1 where clerk_user_id = $2' using v_balance, p_user_id;
      end if;
      insert into public.credit_usage (clerk_user_id, credits_used, action) values (p_user_id, 1, 'brief_generated');
    end if;
  end if;

  insert into public.campaign_brief_versions (
    campaign_id, clerk_user_id, attempt_number, is_selected,
    headline, primary_text, description, cta, copywriter_note, brief_data
  )
  values (
    v_campaign_id, p_user_id, v_attempt, v_attempt = 1,
    p_copy->>'headline', p_copy->>'primary_text', p_copy->>'description',
    p_copy->>'cta', p_copy->>'copywriter_note', p_context
  ) returning id into v_version_id;

  v_result := p_response || jsonb_build_object(
    'campaignId', v_campaign_id,
    'versionId', v_version_id,
    'attemptNumber', v_attempt,
    'credits_balance', v_balance,
    'is_unlimited', v_unlimited
  );

  insert into public.brief_generation_receipts (clerk_user_id, request_id, request_hash, response)
    values (p_user_id, p_request_id, p_request_hash, v_result);

  return v_result;
end;
$_$;


--
-- Name: delete_user_data(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_data(p_user_id text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  anonymous_id text := 'deleted:' || gen_random_uuid();
begin
  delete from public.campaigns where clerk_user_id = p_user_id;
  delete from public.campaign_brief_versions where clerk_user_id = p_user_id;
  delete from public.brief_generation_receipts where clerk_user_id = p_user_id;
  delete from public.capi_events where clerk_user_id = p_user_id;
  delete from public.credit_usage where clerk_user_id = p_user_id;
  delete from public.email_log where user_id = p_user_id;
  delete from public.shopify_refresh_locks where user_id = p_user_id;
  delete from public.rate_limits where key like '%:' || p_user_id;
  update public.api_usage_log set user_id = null where user_id = p_user_id;
  update public.payments
     set clerk_user_id = anonymous_id,
         provider_reference = case when provider_reference like 'gid://%' then provider_reference end
   where clerk_user_id = p_user_id;
  delete from public.user_integrations where clerk_user_id = p_user_id;
end;
$$;


--
-- Name: disconnect_shop_installation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disconnect_shop_installation(p_shop text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  shop text := public.normalize_shop_host(p_shop);
  users text[];
  assignments text;
begin
  select coalesce(array_agg(clerk_user_id), '{}') into users
    from public.user_integrations
   where shop in (public.normalize_shop_host(shopify_store_url), public.normalize_shop_host(shop_domain));
  if shop is null or cardinality(users) = 0 then return 0; end if;

  select string_agg(format('%I = null', column_name), ', ') into assignments
    from information_schema.columns
   where table_schema = 'public' and table_name = 'user_integrations'
     and column_name = any(array['shopify_access_token', 'access_token', 'shopify_refresh_token',
       'refresh_token', 'shopify_token_expires_at', 'token_expires_at', 'shopify_webhook_id']);
  execute format('update public.user_integrations set %s, shopify_uninstalled_at = now() where clerk_user_id = any($1)', assignments)
    using users;
  delete from public.shopify_refresh_locks where user_id = any(users);
  return cardinality(users);
end;
$_$;


--
-- Name: finalize_brief_version(text, uuid, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_brief_version(p_user_id text, p_campaign_id uuid, p_version_id uuid, p_context jsonb, p_copy jsonb, p_status text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v public.campaign_brief_versions%rowtype;
  context jsonb;
begin
  perform 1 from public.campaigns where id = p_campaign_id and clerk_user_id = p_user_id for update;
  if not found then raise exception 'campaign_not_found'; end if;
  select * into v from public.campaign_brief_versions where id = p_version_id and campaign_id = p_campaign_id and clerk_user_id = p_user_id;
  if not found then raise exception 'version_not_found'; end if;
  -- Keep immutable generation evidence; only user selections can be updated here.
  context := coalesce(v.brief_data, '{}'::jsonb) || coalesce(p_context, '{}'::jsonb);
  if v.brief_data is not null then
    context := context || (v.brief_data - 'selectedCta' - 'selectedDuration' - 'selectedStrategyIndex' - 'selectedIntlStrategyIndex' - 'budget_plan');
  end if;
  context := context || jsonb_build_object('generatedCopy', jsonb_build_object(
    'headline', v.headline, 'primaryText', v.primary_text, 'description', v.description, 'cta', v.cta, 'copywriterNote', v.copywriter_note));
  update public.campaign_brief_versions set is_selected = (id = p_version_id) where campaign_id = p_campaign_id and clerk_user_id = p_user_id;
  update public.campaign_brief_versions set brief_data = context where id = p_version_id;
  update public.campaigns set brief_data = context, headline = v.headline, primary_text = v.primary_text,
    description = v.description, cta = coalesce(context->>'selectedCta', v.cta), copywriter_note = v.copywriter_note,
    status = case when p_status = 'complete' then 'complete' else status end, updated_at = now()
    where id = p_campaign_id and clerk_user_id = p_user_id;
end;
$$;


--
-- Name: grant_free_credit(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_free_credit(p_user_id text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  u public.user_integrations%rowtype;
begin
  select * into u from public.user_integrations where clerk_user_id = p_user_id for update;
  if not found or coalesce((to_jsonb(u)->>'free_credit_used')::boolean, true) then
    return false;
  end if;
  perform public.add_user_credits(p_user_id, 1, 0);
  execute 'update public.user_integrations set free_credit_used = true where clerk_user_id = $1'
    using p_user_id;
  return true;
end;
$_$;


